package com.crms.entity;import java.time.Instant;import org.springframework.data.annotation.Id;import org.springframework.data.mongodb.core.mapping.Document;@Document("placement_records") public class PlacementRecord{@Id private Long id;private Student student;private Company company;private String role;private Double packageLpa;private Instant placedAt=Instant.now();public Long getId(){return id;}public void setId(Long v){id=v;}public Student getStudent(){return student;}public void setStudent(Student v){student=v;}public Company getCompany(){return company;}public void setCompany(Company v){company=v;}public String getRole(){return role;}public void setRole(String v){role=v;}public Double getPackageLpa(){return packageLpa;}public void setPackageLpa(Double v){packageLpa=v;}public Instant getPlacedAt(){return placedAt;}}
